/* component.c — the WIT glue for the `parser` component.
 *
 * Exports cosmonic:memory-demo/parsing.parse and imports nothing. The record
 * arrives as plain bytes; the result is a small JSON report (ok) or a plain
 * rejection message (err). No stdio is used, so libc pulls in no WASI import. */
#include "parser.h"   /* generated by `wit-bindgen c` into gen/ */
#include "record.h"

#include <string.h>

/* A tiny bounded string builder: appends are dropped once the buffer is full. */
struct sb {
  char buf[512];
  size_t len;
};

static void sb_put(struct sb *s, const char *text) {
  size_t n = strlen(text);
  size_t room = sizeof s->buf - 1 - s->len;
  if (n > room) n = room;
  memcpy(s->buf + s->len, text, n);
  s->len += n;
  s->buf[s->len] = '\0';
}

static void sb_put_uint(struct sb *s, size_t value) {
  char digits[24];
  size_t i = sizeof digits;
  digits[--i] = '\0';
  do {
    digits[--i] = (char)('0' + value % 10);
    value /= 10;
  } while (value != 0 && i > 0);
  sb_put(s, digits + i);
}

/* Append a JSON string. The parser only accepts printable ASCII, so the only
 * characters that need escaping are the quote and the backslash. */
static void sb_put_json_string(struct sb *s, const char *text) {
  sb_put(s, "\"");
  for (; *text != '\0'; text++) {
    char one[3] = {0, 0, 0};
    if (*text == '"' || *text == '\\') {
      one[0] = '\\';
      one[1] = *text;
    } else {
      one[0] = *text;
    }
    sb_put(s, one);
  }
  sb_put(s, "\"");
}

bool exports_cosmonic_memory_demo_parsing_parse(parser_list_u8_t *record,
                                                parser_string_t *ret,
                                                parser_string_t *err) {
  struct record parsed;
  enum record_status status = record_parse(record->ptr, record->len, &parsed);
  size_t received_total = record->len;
  parser_list_u8_free(record);

  struct sb out = {.len = 0};
  out.buf[0] = '\0';

  if (status != RECORD_OK) {
    sb_put(&out, "rejected: ");
    sb_put(&out, record_status_text(status));
    sb_put(&out, " (received ");
    sb_put_uint(&out, received_total);
    sb_put(&out, " bytes, declared payload ");
    sb_put_uint(&out, parsed.declared_len);
    sb_put(&out, ", capacity ");
    sb_put_uint(&out, RECORD_FIELD_CAP);
    sb_put(&out, ")");
    parser_string_dup(err, out.buf);
    return false;
  }

  sb_put(&out, "{\"field\":");
  sb_put_json_string(&out, parsed.field);
  sb_put(&out, ",\"field_len\":");
  sb_put_uint(&out, parsed.field_len);
  sb_put(&out, ",\"capacity\":");
  sb_put_uint(&out, RECORD_FIELD_CAP);
  sb_put(&out, ",\"bounds_checked\":true}");
  parser_string_dup(ret, out.buf);
  return true;
}
